/* ---------------------------------------------------------------------------
 * Publications: presentation-only restructuring.
 *
 * Publications/publications.md is generated by scripts/bib2pubs.py and must
 * stay in its generated form (the GitHub Action rewrites it). So rather than
 * editing the content, reshape each already-rendered entry
 *
 *     Authors, <em>Title</em>, <strong>Venue</strong>, Year <a>Link</a>
 *
 * into a title-first metadata hierarchy at runtime. Anything that does not
 * match that shape is left exactly as authored, and with JS disabled the
 * original list still renders correctly.
 * ------------------------------------------------------------------------- */
(function () {
  'use strict';

  function textBetween(li, stopAt) {
    var out = '';
    for (var i = 0; i < li.childNodes.length; i++) {
      var n = li.childNodes[i];
      if (n === stopAt) break;
      if (n.nodeType === 3) out += n.textContent;
      else if (n.nodeType === 1) out += n.textContent;
    }
    return out;
  }

  function textAfter(li, startAt, skip) {
    var out = '', seen = false;
    for (var i = 0; i < li.childNodes.length; i++) {
      var n = li.childNodes[i];
      if (n === startAt) { seen = true; continue; }
      if (!seen) continue;
      if (skip.indexOf(n) !== -1) continue;
      if (n.nodeType === 3) out += n.textContent;
    }
    return out;
  }

  function tidy(s) {
    return String(s).replace(/\s+/g, ' ').replace(/^[\s,;·—-]+|[\s,;·—-]+$/g, '').trim();
  }

  function enhanceItem(li) {
    if (li.dataset.pub === '1') return;

    // kramdown renders this as a loose list, so the entry lives in a <p>.
    var host = li.firstElementChild;
    if (!host || host.tagName !== 'P' || li.children.length !== 1) host = li;

    var em = null, strong = null, links = [];
    for (var i = 0; i < host.children.length; i++) {
      var c = host.children[i];
      if (c.tagName === 'EM' && !em) em = c;
      else if (c.tagName === 'STRONG' && !strong) strong = c;
      else if (c.tagName === 'A') links.push(c);
    }
    if (!em) return;                                  // unknown shape — leave alone

    var authors = tidy(textBetween(host, em));
    var title   = em.innerHTML;
    var venue   = strong ? tidy(strong.innerHTML) : '';
    var tail    = textAfter(host, em, [strong].concat(links));
    var ym      = tail.match(/\b(?:19|20)\d{2}\b/);
    var year    = ym ? ym[0] : '';

    if (!authors && !venue && !year) return;

    var frag = document.createDocumentFragment();

    var t = document.createElement('p');
    t.className = 'pub__title';
    t.innerHTML = title;
    frag.appendChild(t);

    if (authors) {
      var a = document.createElement('p');
      a.className = 'pub__authors';
      a.textContent = authors;
      frag.appendChild(a);
    }

    var meta = document.createElement('p');
    meta.className = 'pub__meta';
    if (venue) {
      var v = document.createElement('span');
      v.className = 'pub__venue';
      v.innerHTML = venue;
      meta.appendChild(v);
    }
    if (year) {
      if (venue) meta.appendChild(document.createTextNode(' · '));
      var y = document.createElement('span');
      y.className = 'pub__year';
      y.textContent = year;
      meta.appendChild(y);
    }
    links.forEach(function (link) {
      link.classList.add('pub__link');
      meta.appendChild(link);
    });
    frag.appendChild(meta);

    li.textContent = '';
    li.appendChild(frag);
    li.dataset.pub = '1';
  }

  /* "Preprint" etc. may legitimately have a single entry rendered as a tight
     list; handle both shapes. */
  function items(root) {
    return root.querySelectorAll('ol > li, ul.pubs > li');
  }

  /* A generated section with no entries renders as "_No entries._"; fold it
     away rather than showing an empty heading. It returns on its own once the
     bibliography has an entry in that bucket again. */
  function hideEmptySections(root) {
    var heads = root.querySelectorAll('h2');
    Array.prototype.forEach.call(heads, function (h) {
      var n = h.nextElementSibling;
      if (!n || n.tagName !== 'P') return;
      if (!/^\s*no entries\.?\s*$/i.test(n.textContent)) return;
      h.classList.add('is-empty');
      n.classList.add('is-empty');
    });
  }

  function enhance() {
    var main = document.getElementById('main');
    if (!main || main.getAttribute('data-nav-id') !== 'publications') return;
    var root = main.querySelector('.prose');
    if (!root) return;
    Array.prototype.forEach.call(items(root), enhanceItem);
    hideEmptySections(root);
  }

  window.SBPubs = { enhance: enhance };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', enhance);
  } else {
    enhance();
  }
})();
